#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub struct Quantity { amount_milli: i64, unit: Unit }

impl Quantity {
    pub fn new(amount: f64, unit: Unit) -> Result<Self, QuantityError> {
        if !amount.is_finite() { return Err(QuantityError::NotFinite); }
        Ok(Self { amount_milli: (amount * 1000.0).round() as i64, unit })
    }
}
